const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Villarrica Volcano, Chile
  const aoi = ee.Geometry.Point([-71.936, -39.422]).buffer(5000); // 5km buffer

  const historicalStartDate = '2000-12-01';
  const historicalEndDate = '2021-01-31';
  const recentStartDate = '2021-12-01';
  const recentEndDate = '2022-01-31';

  // 2. Data Acquisition & Check
  const modisSnow = ee.ImageCollection('MODIS/061/MOD10A1').select('NDSI_Snow_Cover');

  // Historical Collection
  const historicalColl = modisSnow
    .filterDate(historicalStartDate, historicalEndDate)
    .filter(ee.Filter.calendarRange(12, 1, 'month')); // Filter for Dec and Jan

  const historicalCollSize = historicalColl.size().getInfo();
  if (historicalCollSize === 0) {
    console.log('Evidence: No historical images found (2000-2020).');
    console.log('C1');
    return;
  }

  // Recent Collection
  const recentColl = modisSnow
    .filterDate(recentStartDate, recentEndDate);

  const recentCollSize = recentColl.size().getInfo();
  if (recentCollSize === 0) {
    console.log('Evidence: No recent images found (2021-2022).');
    console.log('C1');
    return;
  }

  // 3. Processing
  // Create mean composites for both periods.
  // Values > 100 are flags (e.g., cloud, no decision), so they must be masked.
  const historicalMeanImage = historicalColl.mean().updateMask(ee.Image().lte(100));
  const recentMeanImage = recentColl.mean().updateMask(ee.Image().lte(100));

  const scale = 500; // MODIS native scale

  // 4. Calculation
  const historicalStats = historicalMeanImage.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const recentStats = recentMeanImage.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  // 5. Validation & Final Answer
  const historicalMean = historicalStats['NDSI_Snow_Cover_mean'];
  const historicalPixels = historicalStats['NDSI_Snow_Cover_count'];
  const recentMean = recentStats['NDSI_Snow_Cover_mean'];
  const recentPixels = recentStats['NDSI_Snow_Cover_count'];

  console.log(`Historical Images (Dec/Jan, 2000-2020): ${historicalCollSize}`);
  console.log(`Recent Images (Dec/Jan, 2021-2022): ${recentCollSize}`);

  if (historicalPixels === 0 || recentPixels === 0) {
      console.log(`Evidence: No valid pixels after masking.`);
      console.log(`Historical Valid Pixels: ${historicalPixels}`);
      console.log(`Recent Valid Pixels: ${recentPixels}`);
      console.log('C2');
      return;
  }

  if (historicalMean === null || recentMean === null) {
      console.log('Evidence: Calculation resulted in null.');
      console.log(`Historical Mean: ${historicalMean}`);
      console.log(`Recent Mean: ${recentMean}`);
      console.log('C3');
      return;
  }

  console.log(`Historical Mean Snow Cover (2000-2020): ${historicalMean.toFixed(2)}%`);
  console.log(`Recent Mean Snow Cover (2021-2022): ${recentMean.toFixed(2)}%`);

  if (recentMean > historicalMean) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(`An error occurred: ${e}`);
  console.log('D');
});
